/*
 * prog40_bisection_root – reconstructed from the supplied binary.
 *
 * Behaviour (as observed from the decompiled state‑machine):
 *   • No command‑line argument      → prints "NO_INPUT"
 *   • Argument not a pure decimal  → prints "BAD_INPUT"
 *   • Negative number               → prints "BAD_INPUT"
 *   • Number > 1 000 000            → prints "OUT_OF_RANGE"
 *   • Otherwise computes sqrt(n) with a 60‑iteration bisection
 *     (mid = (high‑low)*0.5 + low) and prints the final
 *     approximation with six fractional digits.
 *
 * The constants used in the original binary are:
 *   – 0.5  (stored at _DAT_00102008)
 *   – 0.0  (stored at _DAT_00102010)
 *   – iteration limit 0x3c = 60
 */

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    /* -------------------------------------------------------------
       1. Argument handling
       ------------------------------------------------------------- */
    if (argc < 2) {                     /* no argument supplied */
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* Bad input if nothing was consumed or extra characters remain */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Negative numbers are also considered bad input */
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* Upper bound – the original limits the value to 1 000 000 */
    if (n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* -------------------------------------------------------------
       2. Bisection (square‑root) – 60 iterations
       ------------------------------------------------------------- */
    double low  = 0.0;
    double high = (double)n + 0.0;   /* the original adds a constant that is 0.0 */
    double mid  = 0.0;

    /* The original loops at most 60 times (0x3c) */
    for (int i = 0; i < 60; ++i) {
        mid = (high - low) * 0.5 + low;   /* _DAT_00102008 is 0.5 */
        if ((double)n < mid * mid) {
            high = mid;                  /* n is smaller than mid² */
        } else {
            low = mid;                   /* n is larger or equal to mid² */
        }
    }

    /* Print the final approximation with six fractional digits */
    printf("%.6f\n", mid);
    return 0;
}
